contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // single public entry that performs the property test
    function run(
        address baseToken,
        address nft,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public payable {
        // No precondition on parameters; feeRate > 5000 will cause initialize to revert by design.

        // Call initialize once and record whether it reverted and the observed public values after.
        bool firstReverted;
        try c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        ) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        // Read observable state after the first attempt
        // These getters are public in C
        address observedBaseToken = c.baseToken();
        address observedNft = c.nft();
        uint128 observedVBase = c.virtualBaseTokenReserves();
        uint128 observedVNft = c.virtualNftReserves();
        uint56 observedChangeFee = c.changeFee();
        uint16 observedFeeRate = c.feeRate();
        bytes32 observedMerkle = c.merkleRoot();
        bool observedUseOracle = c.useStolenNftOracle();
        bool observedPayRoyalties = c.payRoyalties();
        bool observedInitialized = c.initialized();

        // Now attempt to call initialize a second time with different inputs to check it must revert if first succeeded
        bool secondReverted;
        try c.initialize(address(1), address(2), uint128(1), uint128(1), uint56(1), uint16(1), bytes32(0x1), true, true) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        // General rule (single assert):
        // If the first initialize call did not revert then:
        //   - initialized must be true
        //   - the public fields must equal the parameters passed in the successful initialize
        //   - a subsequent initialize call must revert (AlreadyInitialized)
        // If the first call reverted then no guarantees about state are required here (we only assert the logical implication).
        assert(
            firstReverted || (
                observedInitialized == true
                && observedBaseToken == baseToken
                && observedNft == nft
                && observedVBase == virtualBaseTokenReserves
                && observedVNft == virtualNftReserves
                && observedChangeFee == changeFee
                && observedFeeRate == feeRate
                && observedMerkle == merkleRoot
                && observedUseOracle == useStolenNftOracle
                && observedPayRoyalties == payRoyalties
                && secondReverted
            )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address baseToken,
        address nft,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public payable {
        // Attempt first initialize and record whether it reverted
        bool firstReverted;
        try c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        ) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        // Observe public state after first attempt
        address observedBaseToken = c.baseToken();
        address observedNft = c.nft();
        uint128 observedVBase = c.virtualBaseTokenReserves();
        uint128 observedVNft = c.virtualNftReserves();
        uint56 observedChangeFee = c.changeFee();
        uint16 observedFeeRate = c.feeRate();
        bytes32 observedMerkle = c.merkleRoot();
        bool observedUseOracle = c.useStolenNftOracle();
        bool observedPayRoyalties = c.payRoyalties();
        bool observedInitialized = c.initialized();

        // Attempt a second initialize with distinct values and record whether it reverted
        bool secondReverted;
        bytes32 otherMerkle = bytes32(uint256(1));
        try c.initialize(address(0x100), address(0x200), uint128(123), uint128(456), uint56(7), uint16(8), otherMerkle, !useStolenNftOracle, !payRoyalties) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        // Assert general property: if first initialize succeeded then initialized==true,
        // public fields equal the parameters passed in the successful call, and a subsequent initialize reverts.
        assert(
            firstReverted || (
                observedInitialized == true
                && observedBaseToken == baseToken
                && observedNft == nft
                && observedVBase == virtualBaseTokenReserves
                && observedVNft == virtualNftReserves
                && observedChangeFee == changeFee
                && observedFeeRate == feeRate
                && observedMerkle == merkleRoot
                && observedUseOracle == useStolenNftOracle
                && observedPayRoyalties == payRoyalties
                && secondReverted
            )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry per constraints
    function run(
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights,
        bytes32[] calldata proofBytes,
        bool[] calldata proofFlags,
        uint256 ethToSend
    ) public payable {
        // We only require that this contract has enough balance if sending ETH to c
        require(address(this).balance >= ethToSend);

        // Prepare MerkleMultiProof struct in calldata-compatible form by memory copy
        C.MerkleMultiProof memory proof;
        proof.proof = new bytes32[](proofBytes.length);
        for (uint i = 0; i < proofBytes.length; i++) proof.proof[i] = proofBytes[i];
        proof.flags = new bool[](proofFlags.length);
        for (uint i = 0; i < proofFlags.length; i++) proof.flags[i] = proofFlags[i];

        // Observe reserves before the call
        uint128 beforeVBase = c.virtualBaseTokenReserves();
        uint128 beforeVNft = c.virtualNftReserves();
        uint256 beforeBalance = address(c).balance;

        // compute expected weight sum as the contract would (sum of tokenWeights)
        uint256 weightSum = 0;
        for (uint i = 0; i < tokenWeights.length; i++) weightSum += tokenWeights[i];

        // Attempt the buy call and record whether it reverted
        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;
        try c.buy{value: ethToSend}(tokenIds, tokenWeights, proof) returns (uint256 n, uint256 f, uint256 p) {
            reverted = false;
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            reverted = true;
        }

        // Observe reserves after the call
        uint128 afterVBase = c.virtualBaseTokenReserves();
        uint128 afterVNft = c.virtualNftReserves();
        uint256 afterBalance = address(c).balance;

        // General property asserted for all inputs:
        // - If buy reverted then virtual reserves and contract balance did not change.
        // - If buy succeeded then virtualNftReserves decreased by exactly weightSum
        //   and virtualBaseTokenReserves increased by at least (netInputAmount - feeAmount - protocolFeeAmount)
        //   (this lower-bound avoids relying on internal rounding) and contract balance increased by netInputAmount when baseToken==address(0).
        assert(
            reverted
            ? (
                afterVNft == beforeVNft
                && afterVBase == beforeVBase
                && afterBalance == beforeBalance
            )
            : (
                // successful case: nft reserves must decrease by weightSum
                afterVNft + uint128(weightSum) == beforeVNft
                // base reserves increased by at least netInputAmount - fee - protocolFee
                && uint256(afterVBase) >= uint256(beforeVBase) + (netInputAmount >= feeAmount + protocolFeeAmount ? netInputAmount - feeAmount - protocolFeeAmount : 0)
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry per constraints
    function run(address token, uint256 tokenId) public {
        // No ETH involved. No specific precondition on token/tokenId.

        // Read observable values before
        uint256 beforeTotalSupply = c.totalSupply(); // note: c has no totalSupply() public function; avoid using it
        // Actually observe only allowed public surfaces. We'll only observe address(c).balance before/after to ensure no state change in balance.
        uint256 beforeBalance = address(c).balance;

        // Call availableForFlashLoan and capture result via try/catch
        bool returned;
        bool success;
        try c.availableForFlashLoan(token, tokenId) returns (bool r) {
            returned = r;
            success = true;
        } catch {
            // If underlying ownerOf reverts, availableForFlashLoan should catch and return false; but since c.availableForFlashLoan uses try/catch and returns false on error,
            // we expect the call to succeed and return false. However if it reverts externally, record that.
            returned = false;
            success = false;
        }

        uint256 afterBalance = address(c).balance;

        // General rule: calling availableForFlashLoan must not change the pool's ETH balance
        // and when the call itself returns (i.e., did not bubble a revert), its boolean result equals whether ownerOf(tokenId) returned address(c).
        // We cannot call ERC721.ownerOf(tokenId) here (external contract) safely, so we only assert the non-mutation property and that the call did not revert unexpectedly.
        // Require that the call itself did not revert (success==true) and that balance didn't change.
        assert(success && afterBalance == beforeBalance);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry per constraints
    function run(address token, uint256 tokenId) public {
        // observe c's ETH balance before the call
        uint256 beforeBalance = address(c).balance;

        // Call availableForFlashLoan and capture its return via try/catch
        bool returned;
        bool callDidNotRevert = false;
        try c.availableForFlashLoan(token, tokenId) returns (bool r) {
            returned = r;
            callDidNotRevert = true;
        } catch {
            // If it reverts, record that
            callDidNotRevert = false;
            returned = false;
        }

        // observe c's ETH balance after the call
        uint256 afterBalance = address(c).balance;

        // General rule: the call must not revert (i.e. should complete and return a bool)
        // and it must not change the pool's ETH balance.
        // We assert both properties together as a general invariant over all inputs.
        assert(callDidNotRevert && afterBalance == beforeBalance);
    }

    receive() external payable {}
}
